function rtEvSpd(S,x,y){let m=1;(S.ev||[]).forEach(e=>{if(e.k==='storm'&&Math.hypot(e.x-x,e.y-y)<e.r)m*=.5});return m}
const rtEvIn=(S,k,x,y)=>(S.ev||[]).some(e=>e.k===k&&Math.hypot(e.x-x,e.y-y)<e.r);
/* イベントの場所：解禁ずみの大陸の陸地のどこか（人が多い大陸ほど選ばれやすい） */
function rtEvSpot(S,cn){const T=rtTer(S),cu=S.cu||1;for(let n=0;n<600;n++){let id=cn;if(!id){const c=S.cs[Math.floor(rnd()*S.cs.length)];id=rnd()<.6&&c&&!c.dead?rtCnAt(S,c.x,c.y)||1:1+Math.floor(rnd()*cu)}const r=RT_CR[id],x=Math.round((r[0]+6+rnd()*(r[2]-r[0]-12))*RT_T),y=Math.round((r[1]+6+rnd()*(r[3]-r[1]-12))*RT_T);if(T.tb[rtTi(x,y)]===0&&T.cn[rtTi(x,y)]===id)return[x,y]}const r=RT_CR[1];return[(r[0]+r[2])/2*RT_T,(r[1]+r[3])/2*RT_T]}
