  {const cv=document.createElement('canvas');cv.width=cv.height=RT_NT;this.ovc=cv;const tx=new T.CanvasTexture(cv);tx.magFilter=T.NearestFilter;tx.minFilter=T.LinearFilter;tx.generateMipmaps=false;this.ovt=tx;const m=new T.Mesh(new T.PlaneGeometry(RT_N,RT_N),new T.MeshLambertMaterial({map:tx,transparent:true,alphaTest:.05,depthWrite:true}));m.rotation.x=-Math.PI/2;m.position.set(RT_N/2,-.06,RT_N/2);m.receiveShadow=true;sc.add(m);this.ovm=m}
